// Imports
import { list_directory_users } from "@/graphql/queries.js";
import SnackBar from "@/components/SnackBar.vue";
import { API, graphqlOperation } from "aws-amplify";
import AddDeleteUsers from "@/components/LookitUPDirectiory/AllDialogs/AddDeleteUsers.vue";
export default {
  // Components
  components: {
    SnackBar,
    AddDeleteUsers
  },
  // Data
  data() {
    return {
      // Table headers
      subscribers: [{
        title: "Name",
        key: "full_user_name",
        sortable: false
      }, {
        title: "Email",
        key: "user_email_id",
        sortable: false
      }, {
        title: "Actions",
        key: "actions",
        sortable: false
      }],
      dataHeaders: [{
        title: "Name",
        key: "full_user_name",
        sortable: false
      }, {
        title: "Email",
        key: "user_email_id",
        sortable: false
      }],
      // Table data and loading state
      tableData: [],
      tableLoading: false,
      // Dialog states
      addDeleteMember: false,
      componentCheck: 0,
      // Component data
      rowInfo: {},
      actionType: "",
      SnackBarComponent: {},
      // Pagination properties
      currentPage: 1,
      itemsPerPage: 10,
      searchQuery: '',
      windowHeight: 0
    };
  },
  // Lifecycle hooks
  created() {
    this.fetch_subscribers_users();
    this.updateWindowHeight();
  },
  mounted() {
    window.addEventListener('resize', this.updateWindowHeight);
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.updateWindowHeight);
  },
  // Computed properties
  computed: {
    filteredItems() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        return this.tableData;
      }
      const searchTerm = this.searchQuery.toLowerCase().trim();
      return this.tableData.filter(member => member.full_user_name && member.full_user_name.toLowerCase().includes(searchTerm) || member.user_email_id && member.user_email_id.toLowerCase().includes(searchTerm));
    },
    totalCount() {
      return this.filteredItems.length;
    },
    pageCount() {
      return Math.ceil(this.filteredItems.length / this.itemsPerPage);
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.filteredItems.slice(start, end);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  // Watchers
  watch: {
    searchQuery() {
      this.currentPage = 1;
    },
    currentPage() {
      // Scroll to top when page changes
      const table = document.querySelector(".modern-data-table");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    }
  },
  // Methods
  methods: {
    // Data fetching methods
    async fetch_subscribers_users() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(list_directory_users, {
          input: {
            directory_id: this.$store.getters.GetFormObject.directory_id
          }
        }));
        this.tableLoading = false;
        this.tableData = [];
        var response = JSON.parse(result.data.list_directory_users);
        if (response.Status == "Success") {
          this.tableData = response.Data;
          localStorage.setItem("directoryMembers", JSON.stringify(response.Data));
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    // User management methods
    delete_user(value) {
      if (value.user_email_id == this.$store.getters.GetFormObject.directory_created_by) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: " You can't delete yourself from the directory since you're the owner.",
          timeout: 5000,
          Top: true
        };
      } else {
        this.actionType = "Delete";
        this.componentCheck = 1;
        this.addDeleteMember = true;
        this.rowInfo = value;
      }
    },
    // Dialog management methods
    close_action() {
      this.addDeleteMember = false;
      this.actionType = "";
    },
    // Notification methods
    succes_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.addDeleteMember = false;
      this.actionType = "";
      this.tableData = [];
      this.currentPage = 1;
      this.searchQuery = '';
      this.fetch_subscribers_users();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.addDeleteMember = true;
    },
    // Utility methods
    updateWindowHeight() {
      this.windowHeight = window.innerHeight - 310; // Adjust height based on header and padding
    }
  }
};
